changeSet.sql:
GRANT USAGE ON SCHEMA forena_probe TO forena_probe_runtime;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA forena_probe TO forena_probe_runtime;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA forena_probe TO forena_probe_runtime;
REVOKE ALL ON forena_probe.databasechangelog, forena_probe.databasechangeloglock FROM forena_probe_runtime;

CREATE TABLE forena_probe.probe_fault (
 id uuid PRIMARY KEY REFERENCES forena_probe.probe_run(id),
 point text NOT NULL CHECK(point IN ('BEFORE_EFFECT','AFTER_EFFECT_COMMIT')),
 consumed_at timestamptz,
 consumed_by text,
 CHECK((consumed_at IS NULL) = (consumed_by IS NULL))
);
REVOKE ALL ON forena_probe.probe_fault FROM PUBLIC, forena_probe_runtime;
GRANT SELECT ON forena_probe.probe_fault TO forena_probe_runtime;
GRANT UPDATE(consumed_at,consumed_by) ON forena_probe.probe_fault TO forena_probe_runtime;
